// WF2 · Explicar fallo (Code, una vez por cada ítem)
// Arma el aviso de Telegram cuando no hubo diagnóstico. La causa sale del
// último intento (el respaldo); si no corrió, del texto de Parsear Respuesta IA.

let error = '';
try { error = String($('IA Vision Gemini Respaldo').first().json.error?.message ?? ''); } catch (e) { /* no corrió */ }

const causa =
  /^503|high demand/i.test(error) ? 'Gemini está saturado' :
  /^429|quota/i.test(error)       ? 'se agotó el cupo de Gemini por ahora' :
  /timeout/i.test(error)          ? 'Gemini no respondió a tiempo' :
  /formato/.test($json.diagnostico_ia?.diagnostico_tecnico ?? '') ? 'la IA respondió en un formato que no se entiende' :
  'Gemini devolvió un error';

const texto_fallo = $json.estado === 'CONSULTA A PEDIDO'
  ? `⚠️ No llegó el diagnóstico de ${$json.planta}: ${causa}. Probá /diagnostico de nuevo en unos minutos.`
  : `⚠️ No hubo diagnóstico de la foto de ${$json.planta}: ${causa}. La alerta y el riego siguen igual.`;

return { json: { ...$json, texto_fallo } };
